using EduVerse.Core.Common;

namespace EduVerse.Core.Gamification;

/// <summary>A main figure of an era (an emoji avatar: no pictures of real people). <c>Figure</c> links an interview.</summary>
public sealed record HistoryPerson(Catalog.Text Name, string Emoji, Catalog.Text Role, string? Figure = null);

/// <summary>One stop of the timeline of a country: its years, what happened, its main figures and something weird but true.</summary>
public sealed record HistoryEra(string Key, string Emoji, int From, int To, Catalog.Text Title, Catalog.Text Story, Catalog.Text Oddity, IReadOnlyList<HistoryPerson> People);

/// <summary>The history of a country as a path through time. <c>Custom</c>: written by the AI for one student.</summary>
public sealed record CountryHistory(string Key, string Flag, Catalog.Text Name, IReadOnlyList<HistoryEra> Eras, bool Custom = false);

/// <summary>
/// Trips through the history of a country: a timeline of eras walked in order, each with a short story, its main
/// figures and a "strange but true" fact, then a 3-question check written by the code from those facts (so every
/// check is different and its answers are always right). Written in advance for a few countries; the AI can write
/// the timeline of any other country (see <see cref="CountryHistoryPrompt"/>).
/// </summary>
public static class Countries
{
    /// <summary>Questions of the check of an era, and how many must be right to pass it.</summary>
    public const int CheckLength = 3;
    public const int PassMark = 2;

    public const int EraXp = 15;
    public const int EraGems = 5;

    /// <summary>Gems for the passport stamp, when every era of a country is passed.</summary>
    public const int StampGems = 30;

    /// <summary>Year shown as "today".</summary>
    public const int Today = 9999;

    private static Catalog.Text T(string s) => Catalog.Text.Of(s);

    private static HistoryPerson P(string name, string emoji, string role, string? figure = null) => new(T(name), emoji, T(role), figure);

