    public static CountryHistory? Find(string? key) => All.FirstOrDefault(c => c.Key == key);

    /// <summary>"218 BC", "1492", "today" in the student's language.</summary>
    public static string Year(int year, TeachLanguage language) => year switch
    {
        >= Today => Lang.T(language, "today", "hoy", "aujourd'hui", "avui"),
        < 0 => (-year).ToString(System.Globalization.CultureInfo.InvariantCulture) + Lang.T(language, " BC", " a. C.", " av. J.-C.", " aC"),
        _ => year.ToString(System.Globalization.CultureInfo.InvariantCulture),
    };

    public static string Years(HistoryEra era, TeachLanguage language)
    {
        ArgumentNullException.ThrowIfNull(era);
        return Year(era.From, language) + " – " + Year(era.To, language);
    }
}
